
import type { DeliveryMethodConfiguration } from './DeliveryMethodConfiguration.js';
import type { SubscriptionCounts } from './SubscriptionCounts.js';

export type DeliveryMethod = { /** Current eligibility, pricing, origin, estimate, and tax configuration. */ "configuration": DeliveryMethodConfiguration; /** Time the method was created. Format: date-time. */ "created_at": string; /** Immutable revision currently used for new quotes. */ "current_delivery_method_revision_id": string; /** Stable delivery method ID. */ "delivery_method_id": string; /** Optional buyer-facing description. */ "description"?: string; /** Ascending display order among methods. Format: int32. */ "display_position"?: number; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing method name. */ "name": string; /** Higher values win recommendation tie-breaks. Format: int32. */ "recommendation_priority"?: number; /** Current method lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked" | (string & {}); "subscription_counts": SubscriptionCounts; /** Delivery mode this method offers. */ "type"?: "shipment" | "local_delivery" | "pickup" | (string & {}); /** Time the method last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for method writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
